import React, { useState, useEffect } from 'react'
import { useHistory } from "react-router-dom"
import { Form, Button, Row, Col, Card, Spinner } from 'react-bootstrap'
import { createCard } from '../actions/cardActions'
import { useDispatch, useSelector } from 'react-redux'
import { Link } from 'react-router-dom'
import Message from './Message'
import DeleteCardComponent from './DeleteCardComponent'

// Current year
const todays_date = new Date()
const current_year = todays_date.getFullYear()


const CreateCardComponent = ({ stripeCards, addressSelected }) => {

    const history = useHistory()
    const dispatch = useDispatch()

    // -----------------------------
    // State
    // -----------------------------

    const [userId] = useState(0)

    const [runCardDeleteHandler, setRunCardDeleteHandler] = useState(false)

    const [differentCard, setDifferentCard] = useState(false)

    const [cardDetails, setCardDetails] = useState(false)

    const [cardDetailsId, setCardDetailsId] = useState(0)

    const [showStripeCard, setShowStripeCard] = useState(false)

    const [deleteCardNumber] = useState("")

    const [email, setEmail] = useState("")

    const [cardNumber, setCardNumber] = useState("")

    const [expMonth, setExpMonth] = useState("")

    const [expYear, setExpYear] = useState("")

    const [cvc, setCvc] = useState("")

    // IMPORTANT
    const [saveCard, setSaveCard] = useState(false)


    // -----------------------------
    // Login reducer
    // -----------------------------

    const userLoginReducer = useSelector(
        state => state.userLoginReducer
    )

    const { userInfo } = userLoginReducer


    // -----------------------------
    // Delete saved card reducer
    // -----------------------------

    const deleteSavedCardReducer = useSelector(
        state => state.deleteSavedCardReducer
    )

    const {
        loading,
        success,
        error
    } = deleteSavedCardReducer


    // -----------------------------
    // Login check
    // -----------------------------

    useEffect(() => {

        if (!userInfo) {

            history.push("/login")

        }

    }, [history, userInfo])


    // -----------------------------
    // Card submit
    // -----------------------------

    const handleCardSubmittion = (e) => {

        e.preventDefault()


        if (!addressSelected) {

            alert(
                "Please select or add your Address to continue"
            )

            return
        }


        // Check card number
        if (cardNumber.length !== 16) {

            alert(
                "Please enter a valid 16 digit card number"
            )

            return
        }


        // Check CVC
        if (cvc.length !== 3) {

            alert(
                "Please enter a valid 3 digit CVC"
            )

            return
        }


        const data = {

            email:
                email === ""
                    ? userInfo.email
                    : email,

            cardNumber: cardNumber,

            expMonth:
                expMonth
                    ? Number(expMonth)
                    : "",

            expYear:
                expYear
                    ? Number(expYear)
                    : "",

            cvc:
                cvc
                    ? Number(cvc)
                    : "",

            // IMPORTANT
            saveCard: saveCard
        }


        // DEBUG
        console.log(
            "CARD DATA SENT:",
            data
        )

        console.log(
            "SAVE CARD:",
            saveCard
        )


        dispatch(
            createCard(data)
        )
    }


    // -----------------------------
    // Pay with saved card
    // -----------------------------

    const payWithSavedCard = (cardData) => {

        if (!addressSelected) {

            alert(
                "Please select or add your Address to continue"
            )

            return
        }


        const data = {

            email: cardData.email,

            cardNumber: cardData.card_number,

            expMonth:
                Number(cardData.exp_month),

            expYear:
                Number(cardData.exp_year),

            cvc:
                Number(cardData.cvc),

            // Don't save again
            saveCard: false
        }


        console.log(
            "PAY WITH SAVED CARD:",
            data
        )


        dispatch(
            createCard(data)
        )
    }


    // -----------------------------
    // Show card details
    // -----------------------------

    const showCardDetails = (cardData) => {

        if (
            cardDetails &&
            cardData.id === cardDetailsId
        ) {

            return (

                <div className="mt-3">

                    <button
                        type="button"
                        onClick={() =>
                            setCardDetails(false)
                        }
                        className="btn btn-outline-danger btn-sm"
                        style={{
                            float: "right"
                        }}
                    >
                        Close
                    </button>


                    <p>
                        <b>Exp Month:</b>{" "}
                        {cardData.exp_month}
                    </p>


                    <p>
                        <b>Exp Year:</b>{" "}
                        {cardData.exp_year}
                    </p>

                </div>
            )
        }


        return null
    }


    // -----------------------------
    // Delete modal toggle
    // -----------------------------

    const toggleRunCardDeleteHandler = () => {

        setRunCardDeleteHandler(
            !runCardDeleteHandler
        )
    }


    // -----------------------------
    // Card deleted
    // -----------------------------

    if (success) {

        alert(
            "Card successfully deleted."
        )

        window.location.reload()
    }


    // -----------------------------
    // UI
    // -----------------------------

    return (

        <div>

            {/* =====================================
                DELETE CARD MODAL
            ===================================== */}

            <DeleteCardComponent
                userId={userId}
                deleteCardNumber={deleteCardNumber}
                runCardDeleteHandler={
                    runCardDeleteHandler
                }
                toggleRunCardDeleteHandler={
                    toggleRunCardDeleteHandler
                }
            />


            {/* =====================================
                DELETE LOADING
            ===================================== */}

            {loading && (

                <div
                    className="d-flex align-items-center mb-3"
                >

                    <h5 className="mb-0">
                        Deleting card
                    </h5>

                    <Spinner
                        animation="border"
                        size="sm"
                        className="ml-2"
                    />

                </div>
            )}


            {/* =====================================
                ERROR
            ===================================== */}

            {error && (

                <Message variant="danger">
                    {error}
                </Message>

            )}


            {/* =====================================
                NEW CARD
            ===================================== */}

            <div className="card px-4 py-4">

                <button
                    type="button"
                    className={
                        showStripeCard
                            ? "btn btn-sm btn-danger mb-3"
                            : "btn btn-sm btn-primary mb-3"
                    }
                    onClick={() =>
                        setShowStripeCard(
                            !showStripeCard
                        )
                    }
                >

                    {showStripeCard
                        ? "Close"
                        : "Enter Stripe Card"}

                </button>


                {showStripeCard && (

                    <Form
                        onSubmit={
                            handleCardSubmittion
                        }
                    >

                        {/* =====================================
                            EMAIL
                        ===================================== */}

                        {differentCard ? (

                            <Form.Group>

                                <Form.Label>
                                    <b>
                                        Card Holder Email Address
                                    </b>
                                </Form.Label>


                                <Form.Control
                                    autoFocus
                                    type="email"
                                    value={email}
                                    onChange={(e) =>
                                        setEmail(
                                            e.target.value
                                        )
                                    }
                                    placeholder="Email address linked with the card"
                                    required
                                />

                            </Form.Group>

                        ) : (

                            <div className="mb-2">

                                <b>
                                    Default Customer Email:
                                </b>{" "}

                                {userInfo.email}

                            </div>
                        )}


                        {/* =====================================
                            EMAIL SWITCH
                        ===================================== */}

                        <p>

                            <Link
                                to="#"
                                onClick={(e) => {

                                    e.preventDefault()

                                    setDifferentCard(
                                        !differentCard
                                    )

                                    setEmail("")

                                    // Reset save card
                                    setSaveCard(false)
                                }}
                            >

                                {differentCard
                                    ? "Use Your default Email"
                                    : "Use a different Card"}

                            </Link>

                        </p>


                        {/* =====================================
                            CARD NUMBER
                        ===================================== */}

                        <Form.Group className="mb-3">

                            <Form.Label>
                                <b>
                                    Card Number
                                </b>
                            </Form.Label>


                            <Form.Control
                                type="text"
                                inputMode="numeric"
                                pattern="[0-9]{16}"
                                value={cardNumber}
                                onChange={(e) => {

                                    const value =
                                        e.target.value
                                            .replace(
                                                /\D/g,
                                                ""
                                            )
                                            .slice(
                                                0,
                                                16
                                            )

                                    setCardNumber(value)
                                }}
                                placeholder="Enter your 16 digit card number"
                                maxLength="16"
                                required
                            />

                        </Form.Group>


                        {/* =====================================
                            EXPIRY + CVC
                        ===================================== */}

                        <Row>

                            {/* EXP MONTH */}

                            <Col>

                                <Form.Group
                                    className="mb-3"
                                >

                                    <Form.Label>
                                        <b>
                                            Exp Month
                                        </b>
                                    </Form.Label>


                                    <Form.Control
                                        as="select"
                                        value={expMonth}
                                        onChange={(e) =>
                                            setExpMonth(
                                                e.target.value
                                            )
                                        }
                                        required
                                    >

                                        <option value="">
                                            -- --
                                        </option>


                                        {Array.from(
                                            {
                                                length: 12
                                            },
                                            (_, i) => (

                                                <option
                                                    key={i + 1}
                                                    value={i + 1}
                                                >
                                                    {i + 1}
                                                </option>

                                            )
                                        )}

                                    </Form.Control>

                                </Form.Group>

                            </Col>


                            {/* EXP YEAR */}

                            <Col>

                                <Form.Group
                                    className="mb-3"
                                >

                                    <Form.Label>
                                        <b>
                                            Exp Year
                                        </b>
                                    </Form.Label>


                                    <Form.Control
                                        as="select"
                                        value={expYear}
                                        onChange={(e) =>
                                            setExpYear(
                                                e.target.value
                                            )
                                        }
                                        required
                                    >

                                        <option value="">
                                            -- --
                                        </option>


                                        {Array.from(
                                            {
                                                length: 21
                                            },
                                            (_, i) => (

                                                <option
                                                    key={
                                                        current_year + i
                                                    }
                                                    value={
                                                        current_year + i
                                                    }
                                                >
                                                    {
                                                        current_year + i
                                                    }
                                                </option>

                                            )
                                        )}

                                    </Form.Control>

                                </Form.Group>

                            </Col>


                            {/* CVC */}

                            <Col>

                                <Form.Group
                                    className="mb-3"
                                >

                                    <Form.Label>
                                        <b>
                                            CVC Number
                                        </b>
                                    </Form.Label>


                                    <Form.Control
                                        type="text"
                                        inputMode="numeric"
                                        pattern="[0-9]{3}"
                                        value={cvc}
                                        onChange={(e) => {

                                            const value =
                                                e.target.value
                                                    .replace(
                                                        /\D/g,
                                                        ""
                                                    )
                                                    .slice(
                                                        0,
                                                        3
                                                    )

                                            setCvc(value)
                                        }}
                                        placeholder="123"
                                        maxLength="3"
                                        required
                                    />

                                </Form.Group>

                            </Col>

                        </Row>


                        {/* =====================================
                            SAVE CARD CHECKBOX
                        ===================================== */}

                        {!differentCard && (

                            <Form.Group className="mb-3">

                                <Form.Check
                                    type="checkbox"
                                    id="saveCard"
                                    label="Save my card for future payments"
                                    checked={saveCard}
                                    onChange={(e) =>
                                        setSaveCard(
                                            e.target.checked
                                        )
                                    }
                                />

                            </Form.Group>

                        )}


                        {/* =====================================
                            SUBMIT
                        ===================================== */}

                        <Button
                            className="btn-sm"
                            variant="primary"
                            type="submit"
                        >

                            Submit

                        </Button>

                    </Form>
                )}

            </div>


            {/* =====================================
                SAVED CARDS
            ===================================== */}

            <div className="my-4 card px-4 py-4">

                <h5>
                    Saved Card
                </h5>


                {stripeCards &&
                stripeCards.length > 0 ? (

                    stripeCards.map(
                        (cardData) => (

                            <div
                                key={cardData.id}
                                className="mb-3"
                            >

                                <Card
                                    className="p-3"
                                    style={{
                                        border:
                                            "1px solid #C6ACE7"
                                    }}
                                >

                                    {/* CARD NUMBER */}

                                    <p>

                                        <b>
                                            Card Number:
                                        </b>{" "}

                                        XXXX XXXX XXXX{" "}

                                        {
                                            cardData.card_number
                                                ? cardData.card_number.slice(-4)
                                                : "----"
                                        }

                                    </p>


                                    {/* CARD ACTIONS */}

                                    <div>

                                        {showCardDetails(
                                            cardData
                                        )}


                                        <button
                                            type="button"
                                            onClick={() => {

                                                setCardDetails(
                                                    true
                                                )

                                                setCardDetailsId(
                                                    cardData.id
                                                )
                                            }}
                                            className="btn btn-sm btn-outline-primary"
                                        >

                                            Show Card Details

                                        </button>


                                        <button
                                            type="button"
                                            onClick={() =>
                                                payWithSavedCard(
                                                    cardData
                                                )
                                            }
                                            className="ml-2 btn btn-sm btn-outline-primary"
                                        >

                                            Pay with this Card

                                        </button>

                                    </div>

                                </Card>


                                {/* EDIT CARD */}

                                <span
                                    onClick={() =>
                                        history.push(
                                            "/stripe-card-details/"
                                        )
                                    }
                                    style={{
                                        cursor: "pointer"
                                    }}
                                >

                                    <i
                                        title="Edit card"
                                        className="fas fa-edit fa-lg edit-button-css mr-2"
                                    ></i>

                                </span>

                            </div>

                        )
                    )

                ) : (

                    <p className="text-muted mb-0">
                        No saved card.
                    </p>

                )}

            </div>

        </div>
    )
}


export default CreateCardComponent
